import numpy as np

def feature(kind, line, depth, fail_cov, pass_cov, covered, edited, line_tries, status, error, outcomes, tries, budget):
    """Constant kinds score q=1-median(min(err,1)) of wrong-value failures, structural kinds score q-1, variable 0."""
    e = error[status == 1]
    if e.size > 0:
        emed = float(np.median(np.minimum(e, 1.0)))
    else:
        emed = 1.0
    q = 1.0 - emed
    is_const = (kind >= 2) & (kind <= 4)
    is_struct = (kind == 0) | (kind == 1) | (kind == 6) | (kind == 7) | (kind == 8)
    return np.where(is_const, q, np.where(is_struct, q - 1.0, 0.0))

import numpy as np

def feature(kind, line, depth, fail_cov, pass_cov, covered, edited, line_tries, status, error, outcomes, tries, budget):
    """1 minus the maximum Jaccard similarity between a candidate's covered-test set and the covered-test sets of lines already kept (0 if none kept)."""
    k = covered.shape[0]
    cov = covered.astype(float)
    kept = edited.astype(bool)
    if not kept.any():
        return np.zeros(k)
    K = np.unique(cov[kept], axis=0)
    if K.shape[0] == 0:
        return np.zeros(k)
    Inter = cov @ K.T
    union = cov.sum(1)[:, None] + K.sum(1)[None, :] - Inter
    J = np.where(union > 0, Inter / np.maximum(union, 1e-12), 0.0)
    m = J.max(axis=1)
    return 1.0 - m

import numpy as np

def feature(kind, line, depth, fail_cov, pass_cov, covered, edited, line_tries, status, error, outcomes, tries, budget):
    """(1 - line/Lmax) for candidates whose line some failing test executes, else 0."""
    line = np.asarray(line, dtype=float)
    fail_cov = np.asarray(fail_cov, dtype=float)
    lmax = float(np.max(line)) if line.size else 1.0
    if not np.isfinite(lmax) or lmax < 1.0:
        lmax = 1.0
    vals = (1.0 - line / lmax) * (fail_cov > 0).astype(float)
    return np.nan_to_num(vals, nan=0.0, posinf=0.0, neginf=0.0)

import numpy as np

def feature(kind, line, depth, fail_cov, pass_cov, covered, edited, line_tries, status, error, outcomes, tries, budget):
    """+1 if the patch's line is executed by at least one currently failing test, -1 if by none, 0 if no failing tests."""
    fail_cov = np.asarray(fail_cov)
    F = int(outcomes[1:].sum())
    if F == 0:
        return np.zeros(fail_cov.shape[0], dtype=float)
    return np.where(fail_cov > 0, 1.0, -1.0)

import numpy as np

def feature(kind, line, depth, fail_cov, pass_cov, covered, edited, line_tries, status, error, outcomes, tries, budget):
    """-1.0 for candidates on a line where a patch was kept earlier, else 0.0."""
    return np.where(edited, -1.0, 0.0)
